    openlog("InterceptLib", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Custom shared library successfully loaded.");

    // Log LD_PRELOAD environment variable
    char *ld_preload = getenv("LD_PRELOAD");
    if (ld_preload != NULL) {
        syslog(LOG_INFO, "LD_PRELOAD=%s", ld_preload);
    } else {
        syslog(LOG_WARNING, "LD_PRELOAD is not set.");
    }

    closelog();
