            syslog(LOG_ERR, "Failed to locate original write function: %s", dlerror());
            closelog();
            return -1;
        }
    }

    // Log the intercepted call
    openlog("InterceptLib", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Intercepted write call: fd=%d, count=%zu", fd, count);
    closelog();

    // Call the original write function
    return original_write(fd, buf, count);
